import spidev
import time
import signal
import os

class LoadCellReader:
    def __init__(self):
        self.spi = None
        self.adc_channel = 0  # MCP3002 channel 0 for 10-bit ADC
        self.raw_data = None
        self.weight = None

    def send_spi_command(self, spi, data):
        try:
            response = spi.xfer2(data)
            return response
        except (OSError, IOError) as e:
            print(f"Error sending SPI command: {e}")
            return []

    def extract_10bit(self, response):
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        try:
            spi = spidev.SpiDev()
            spi.open(0, 0)  # /dev/spidev0.0, max_speed_hz=50000, mode=0b00, bits_per_word=8
            if spi is None:
                raise OSError("Failed to open SPI device.")

            data = [0x01, 0x80, 0x00]  # MCP3002 command for single-ended mode, channel 0
            response = self.send_spi_command(spi, data)
            if not response:
                raise IOError("Failed to read from MCP3002.")

            self.raw_data = self.extract_10bit(response)
            return self.raw_data

        except (OSError, IOError) as e:
            print(f"Error reading from MCP3002: {e}")
            return None

        finally:
            if self.spi:
                self.spi.close()

    def convert_to_weight(self):
        if self.raw_data is None:
            return None

        weight = float(self.raw_data) * (5.0 / 1023.0)
        return round(weight, 2)

    def close(self):
        if self.spi:
            self.spi.close()

    def main(self):
        while True:
            try:
                raw_data = self.read_raw_data()
                if raw_data is not None:
                    weight = self.convert_to_weight()
                    print(f'Weight: {weight} kg')
                    time.sleep(0.5)
                else:
                    print("Failed to read data from the load cell.")
                    time.sleep(0.5)

            except KeyboardInterrupt:
                print("Program terminated by user.")
                self.close()

            except Exception as e:
                print(f"Unexpected error: {e}")
                self.close()

            finally:
                # Handle SIGTERM to ensure a clean shutdown
                signal.signal(signal.SIGTERM, self.close)

if __name__ == "__main__":
    reader = LoadCellReader()
    reader.main()

