import smbus
import time
import threading

# Constants
ADS1115_I2C_ADDRESS = 0x48
CHANNELS = [0, 1, 2, 3]  # AIN0 to AIN3
FULL_SCALE_VOLTAGE = 4.096  # Volts
SAMPLE_RATE = 128  # Samples per second
CONVERSION_TIMEOUT_MS = 100  # Milliseconds timeout for conversion

class ADS1115:
    def __init__(self, i2c_bus):
        self.i2c_bus = i2c_bus
        self.adc = self._initialize_adc()

    def _initialize_adc(self):
        try:
            # Attempt to communicate with the ADS1115
            i2c = smbus.SMBus(self.i2c_bus)
            if i2c.read_byte_data(ADS1115_I2C_ADDRESS, 0x00) != 0x00:
                raise ValueError("Failed to communicate with ADS1115")

            # Set configuration registers
            self.adc.write_byte_data(ADS1115_I2C_ADDRESS, 0x00, 0b00000000)  # Single-ended mode
            self.adc.write_byte_data(ADS1115_I2C_ADDRESS, 0x01, 0b00000000)  # PGA Gain = 1
            self.adc.write_byte_data(ADS1115_I2C_ADDRESS, 0x02, 0b00000000)  # Data rate = 128 sps

            return self.adc
        except Exception as e:
            print(f"Error initializing ADS1115: {e}")
            return None

    def read_channels(self):
        while True:
            try:
                # Start conversion for all channels
                self.adc.write_byte_data(ADS1115_I2C_ADDRESS, 0x08, 0b00001111)  # AIN0-3

                # Poll OS bit (bit 15) until conversion complete or timeout
                for channel in CHANNELS:
                    while True:
                        if self.adc.read_byte_data(ADS1115_I2C_ADDRESS, 0x00) & 0x80 == 0:  # OS bit clear (conversion complete)
                            break
                        if time.time() > time.time() + CONVERSION_TIMEOUT_MS:
                            print(f"Timeout error for channel {channel}")
                            continue

                    # Read the 16-bit signed integer value
                    value = self.adc.read_adc(channel)
                    print(f"AIN{channel}: {value}")

            except Exception as e:
                print(f"Error reading channel {CHANNELS.index(e.args[0])}: {e}")

            # Sleep for 50ms to meet the 50ms interval requirement
            time.sleep(0.05)

    def close(self):
        if self.adc:
            self.adc.close()

# Main script
if __name__ == "__main__":
    try:
        i2c_bus = 1  # Assuming I2C bus 1
        adc = ADS1115(i2c_bus)
        adc.read_channels()
    except KeyboardInterrupt:
        print("Exiting cleanly...")
    finally:
        if hasattr(adc, 'close'):
            adc.close()

