logger = logging.getLogger(__name__)

# Flask application
app = Flask(__name__)
CORS(app)  # Enable CORS for web streaming
socketio = SocketIO(app)

# GPIO button for toggling live preview
toggle_button = Button(17)  # GPIO 17

# Camera initialization and object detection logic
class Camera:
    def __init__(self, width=640, height=480, flip_vertical=True):
        self.camera = PiCamera(resolution=(width, height), framerate=30, flip_vertical=flip_vertical)
        self.camera.wear(PiCameraWear())
        self.stream = io.BytesIO()
        self.lock = threading.Lock()

    def start_capture(self):
        with self.lock:
            self.camera.capture(self.stream, format="jpeg")
            self.stream.seek(0)
            return self.stream.read()

    def get_frame(self):
        with self.lock:
            return self.start_capture()

    def get_object(self, classifier):
        jpeg_bytes = self.get_frame()
        detected = classifier.detect(jpeg_bytes)
        return jpeg_bytes, detected

    def get_object_with_basic_motion_detection(self):
        jpeg_bytes = self.get_frame()
        detected, is_motion = self.classifier_with_motion_detection.detect(jpeg_bytes)
        return jpeg_bytes, is_motion

    @staticmethod
def initialize_camera():
    try:
        camera = Camera()
        camera.start()
        return camera
    except Exception as e:
        logger.error(f"Camera initialization failed: {e}")
        os._exit(1)

def check_for_objects():
    global config
    while True:
        if config.classifier_name == 'motion_detector':
            jpeg_bytes, is_motion = Camera.get_object_with_basic_motion_detection()
        else:
            jpeg_bytes, is_detected = Camera.get_object(config.classifier)

        if is_motion or is_detected:
            if config.send_email_notifications and time.time() - config.last_email_time >= config.email_send_interval:
                try:
                    mail_config.send_email(jpeg_bytes, config)
                    config.last_email_time = time.time()
                except Exception as e:
                    logger.error(f"Email sending failed: {e}")

        time.sleep(config.check_interval)

def start_background_thread():
    global config
    config = config.load()
    if not initialize_camera():
        print("Camera initialization failed. Exiting.")
        os._exit(1)

    thread = threading.Thread(target=check_for_objects)
    thread.start()

