        serial_port = serial.Serial(SERIAL_PORT, baudrate=BAUD_RATE, bytesize=8, parity=NO_PARITY, stopbits=ONE_STOP_BIT, rtsfalse=True, dsirdetected=False, timeout=1)
        serial_port.write(b'Opening serial port...\r\n')
        return serial_port
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def transmit_data(serial_port, data):
    try:
        serial_port.write(data.encode(UTF_8))
        print(f"Transmitted: {len(data)} bytes to the device.")
    except serial.SerialException as e:
        print(f"Error transmitting data: {e}")

def handle_user_input(serial_port):
    while True:
        user_input = input("Enter text (type 'q' to quit): ")
        if user_input.lower() == 'q':
            break
        try:
            prepended_input = 'X' + user_input
            transmit_data(serial_port, prepended_input)
        except KeyboardInterrupt:
            print("Exiting due to user interrupt.")
            break

def main():
    try:
        with closing(open_serial_port()) as serial_port:
            if serial_port is None:
                print("Failed to open the serial port. Exiting.")
                return

            while True:
                handle_user_input(serial_port)

            print("Exiting gracefully. Goodbye!")
    except KeyboardInterrupt:
        print("Exiting due to user interrupt.")
    except Exception as e:
        print(f"An error occurred: {e}")
        # Ensure the serial port is closed even if an error occurred
        if serial_port is not None:
            serial_port.close()

if __name__ == "__main__":
