import os
import time
import logging
import contextlib
from PIL import Image
from PIL import ImageOps
from io import BytesIO
import giflib
from luma.core.display import display
from paho.mqtt.client import Client, MQTTException

logging.basicConfig(level=logging.INFO)

class AnimatedGif:
    def __init__(self, display, folder_path=".", width=None, height=None):
        self.display = display
        self.folder_path = folder_path
        self.width = width if width is not None else display.width
        self.height = height if height is not None else display.height
        self.files = []
        self.current_file = None
        self.is_running = False
        self.loop_count = 0
        self.frames = []
        self.client = None

    def load_files(self):
        try:
            for file_name in os.listdir(self.folder_path):
                if file_name.endswith(".gif"):
                    file_path = os.path.join(self.folder_path, file_name)
                    with contextlib.closing(giflib.GifReader(file_path)) as gif:
                        if gif.is_animated:
                            self.files.append(file_name)
                            logging.info(f"Loaded animated GIF: {file_name}")
                        else:
                            logging.warning(f"{file_name} is not an animated GIF.")
        except FileNotFoundError:
            logging.error("No valid GIF files found in the folder.")
            raise

    def preload(self, file_name):
        try:
            with contextlib.closing(giflib.GifReader(open(file_name, 'rb'))) as gif:
                self.loop_count = gif.info.get('loop', 0)
                self.frames = []
                for i, frame in enumerate(gif):
                    duration_ms = frame.info.get('duration', 100)
                    frame_image = frame.to_image()
                    padded_image = ImageOps.pad(frame_image, (self.width, self.height), 'black')
                    frame_duration = duration_ms / 1000
                    self.frames.append(Frame(image=padded_image, duration=frame_duration, loop_count=self.loop_count))
                self.current_file = file_name
                logging.info(f"Preloaded {self.current_file}")
        except Exception as e:
            logging.error(f"Error preloading {self.current_file}: {e}")

    class Frame:
        def __init__(self, image, duration, loop_count):
            self.image = image
            self.duration = duration
            self.loop_count = loop_count

    def play(self):
        if not self.files:
            logging.error("No valid GIF files to play.")
            return False

        if not self.current_file:
            self.preload(self.current_file)

        while self.is_running:
            start_time = time.monotonic()
            if self.loop_count == 0:
                self.loop_count = self.frames[-1].duration
            for frame in self.frames:
                if self.loop_count > 0 and self.loop_count == frame.duration:
                    self.loop_count -= frame.duration
                try:
                    self.display.display(frame.image)
                    time.sleep(frame.duration / 1000 - (time.monotonic() - start_time))
                except Exception as e:
                    logging.error(f"Error displaying frame: {e}")
                    return False
            if self.loop_count == 0:
                self.loop_count = self.frames[-1].duration
                if self.loop_count == 0:
                    self.is_running = False
                    return True

    def run(self):
        while self._is_running:
            self.play()

    def stop(self):
        self._is_running = False

    def on_sigint(self):
        logging.info("Animation stopped due to SIGINT/SIGTERM signal.")
        self.stop()

    def on_connect(self, client, userdata, flags, rc):
        logging.info("Connected with result code "+str(rc))
        client.subscribe("animated_gif_control")

    def on_message(self, client, userdata, msg):
        topic = msg.topic
        payload = msg.payload
        if topic == "animated_gif_control":
            if payload == "stop":
                self.stop()
            elif payload == "restart":
                self.run()

    def start_animation(self):
        self.client = Client("mqtt://localhost")
        self.client.on_connect = self.on_connect
        self.client.on_message = self.on_message
        self.client.loop_forever()

    def __del__(self):
        if self.client:
            self.client.loop_stop()
            self.client.disconnect()
        self.display.release()

if __name__ == "__main__":
    display_obj = display.SSD1306_I2C(128, 64)
    animated_gif = AnimatedGif(display_obj, "/path/to/gif/files")
    animated_gif.start_animation()
    animated_gif.run()

