import time
import signal
import gpiozero
import hcsr04
import paho.mqtt.client as mqtt

TRIGGER_PIN = 17
ECHO_PIN = 18
LED_PIN = 2
SAFE_DISTANCE = 20
SHUTDOWN_MSG = "Shutting down the parking sensor system."

def setup_sensor():
    try:
        sensor = hcsr04.HCSR04(trigger_pin=TRIGGER_PIN, echo_pin=ECHO_PIN, temperature=20)
        sensor.init()
        print(f"HC-SR04 sensor initialized with trigger pin {TRIGGER_PIN} and echo pin {ECHO_PIN}")
        return sensor
    except Exception as e:
        print(f"Error initializing HC-SR04 sensor: {e}")
        return None

def setup_led():
    try:
        led = gpiozero.LED(LED_PIN)
        led.on()
        print(f"LED on pin {LED_PIN} initialized and turned on")
        return led
    except Exception as e:
        print(f"Error initializing LED on pin {LED_PIN}: {e}")
        return None

def read_distance(sensor):
    try:
        distance = sensor.distance_cm()
        print(f"Distance: {distance} cm, LED state: {led.is_on()}")
        if distance <= SAFE_DISTANCE:
            led.on()
        else:
            led.off()
    except Exception as e:
        print(f"Error reading distance: {e}")
        distance = SAFE_DISTANCE + 10
        led.off()

def shutdown_signal_handler(signum, frame):
    global led, sensor
    print(SHUTDOWN_MSG)
    led.off()
    if sensor is not None:
        sensor.deinit()

def main():
    # Install signal handler for SIGINT and SIGTERM
    signal.signal(signal.SIGINT, shutdown_signal_handler)
    signal.signal(signal.SIGTERM, shutdown_signal_handler)

    try:
        sensor = setup_sensor()
        if sensor is not None:
            led = setup_led()

            if sensor is not None and led is not None:
                while True:
                    read_distance(sensor)
                    time.sleep(0.1)

            # Clean up on exit
            try:
                sensor.deinit()
                led.off()
            finally:
                print("Exiting...")

    except Exception as e:
        print(f"An error occurred: {e}")
        # Clean up on unexpected exit
        try:
            if sensor is not None:
                sensor.deinit()
            led.off()
        finally:
            print("Exiting...")

if __name__ == "__main__":
    main()

