import smbus2
import datetime
from struct import unpack

# BME280 I2C address and registers
I2C_ADDRESS = 0x76
HUMIDITY_OVERSAMPLING_REGISTER = 0xF2
CONTROL_MEASUREMENT_REGISTER = 0xF4
RAW_HUMIDITY_REGISTERS = [0xFD, 0xFE]
HUMIDITY_CALIBRATION_REGISTERS = [0xA1] + list(range(0xE1, 0xE9, 2))
COMFORT_BANDS = {'too_dry': (0, 30), 'dry': (30, 40), 'comfortable': (40, 60), 'too_humid': (60, float('inf'))}

class BME280:
    def __init__(self, i2c_bus=1):
        self.i2c_bus = i2c_bus
        self.bus = smbus2.SMBus(i2c_bus)
        try:
            self.bus.write_byte_data(I2C_ADDRESS, HUMIDITY_OVERSAMPLING_REGISTER, 0x01)
            self.bus.write_byte_data(I2C_ADDRESS, CONTROL_MEASUREMENT_REGISTER, 0x3F)
        except OSError as e:
            print(f"I2C error: {e}")
            return

    def read_humidity_coefficients(self):
        coefficients = []
        for reg in HUMIDITY_CALIBRATION_REGISTERS:
            try:
                value = self.bus.read_i2c_block_data(I2C_ADDRESS, reg, 2)
                if reg == 0xE1:
                    # Split dig_H4 and dig_H5 LSB nibble from register 0xE5
                    coefficients.append(unpack('!B', value)[0])
                    coefficients.append(unpack('!B', value[1] >> 4))
                else:
                    coefficients.append(unpack('!B', value))
            except OSError as e:
                print(f"I2C error reading register {reg}: {e}")
        return coefficients

    def read_raw_humidity(self):
        try:
            humidity_low = self.bus.read_byte_data(I2C_ADDRESS, RAW_HUMIDITY_REGISTERS[0])
            humidity_high = self.bus.read_byte_data(I2C_ADDRESS, RAW_HUMIDITY_REGISTERS[1])
            return humidity_low, humidity_high
        except OSError as e:
            print(f"I2C error reading humidity registers: {e}")
            return None, None

    def calculate_humidity(self, raw_humidity_low, raw_humidity_high):
        if raw_humidity_low is None or raw_humidity_high is None:
            return None

        t_fine = 20000  # Approximate 25°C
        b1 = 0x5A
        b2 = 0x34
        b3 = 0x29
        b4 = 0x2C

        # BME280 datasheet compensation formula
        Qc = ((b1 * raw_humidity_low + b2 * raw_humidity_high + b3) >> 8) - (b4 * (t_fine // 65536))
        Qn = ((b1 * raw_humidity_low + b2 * raw_humidity_high + b3) & 0x00FF) - (b4 * (t_fine % 65536) // 65536)

        Q = Qc + Qn * (1 << 8)
        RH = (Q * 125.0) / 65535.0

        return RH

    def get_humidity_band(self, humidity):
        for band, lower_bound, upper_bound in COMFORT_BANDS.items():
            if lower_bound <= humidity <= upper_bound:
                return band

    def read_and_log_humidity(self, iterations=5):
        for _ in range(iterations):
            try:
                coefficients = self.read_humidity_coefficients()
                raw_humidity_low, raw_humidity_high = self.read_raw_humidity()
                if raw_humidity_low is not None and raw_humidity_high is not None:
                    humidity = self.calculate_humidity(raw_humidity_low, raw_humidity_high)
                    if humidity is not None:
                        band = self.get_humidity_band(humidity)
                        timestamp = datetime.datetime.now().isoformat()
                        print(f"{timestamp}: Humidity: {humidity:.2f}%, Band: {band}")
            except OSError as e:
                print(f"I2C error during reading: {e}")

    def close(self):
        self.bus.close()

# Example usage
try:
    bme280 = BME280()
    bme280.read_and_log_humidity()
finally:
    bme280.close()

