class PIDHandler:
    def __init__(self):
        self.global_err_state = False
        self.last_msg = None
        self.pwm_device = None
        self.digital_device = None

        # Initialize logging
        logging.basicConfig(level=logging.INFO)

        try:
            # Initialize GPIO
            self.pwm_device = PWMOutputDevice(18, pulse_width=0, frequency=1000) if self.is_pwm_enabled() else \
                                OutputDevice(15)
            self.digital_device = self.pwm_device if self.is_pwm_enabled() else None

            # Register signal handlers
            import signal
            signal.signal(signal.SIGINT, self.cleanup)
            signal.signal(signal.SIGTERM, self.cleanup)

            # Start with error output off
            self.set_error_output(False)
        except Exception as e:
            logging.error(f"Error initializing GPIO: {e}")
            self.digital_device = None
            self.pwm_device = None

    def is_pwm_enabled(self):
        return True  # Placeholder, can be made dynamic based on requirements

    def update_error_output(self):
        if self.is_pwm_enabled():
            duty_cycle = int(self.global_err_state * 100)
            self.pwm_device.pulse_width = duty_cycle
        else:
            self.digital_device.value = self.global_err_state

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self):
        while True:
            try:
                # Receive message with non-blocking
                msg = self.zmq_socket.recv(zmq.NOBLOCK)
                if msg is None:
                    continue

                # Update last message timestamp
                self.last_msg = datetime.now()

                # Check for 20-second timeout
                if (datetime.now() - self.last_msg).seconds > 20:
                    self.set_error_output(True)

                # Process subscription callbacks here
                # Example callback
                print(f"Received message at {self.last_msg}")

            except zmq.Again:
                # Handle EAGAIN by checking the timeout
                pass

    def cleanup(self):
        if self.digital_device:
            self.digital_device.value = False  # Ensure safe shutdown
            self.digital_device = None
        if self.pwm_device:
            self.pwm_device.stop()
            self.pwm_device = None

    def start_zmq(self, context, socket):
        self.zmq_socket = socket
        context.bind("tcp://*:5555")  # Example binding

    def run(self):
        self.start_zmq(zmq.Context(), self.handle_message)
        try:
            while True:
                time.sleep(1)  # Simple polling loop for demonstration
        except KeyboardInterrupt:
            self.cleanup()
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            self.cleanup()

# Example usage
