class OutputPinError(Exception):
    pass

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int) -> None:
        if not 0 <= pin_number <= 31:
            raise OutputPinError("Pin number must be in the range 0-31.")

        if initial_value not in [0, 1]:
            raise OutputPinError("Value must be 0 or 1.")

        self.pi = None
        self.pin_number = pin_number
        self.initial_value = initial_value

        try:
            self.pi = pigpio.pi()
