        except pigpio.Error as e:
            print(f"Error connecting to pigpio: {e}")
            self.pi = None

        if self.pi is not None:
            try:
                self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
                self.pi.write(self.pin_number, self.initial_value)
            except pigpio.Error as e:
                print(f"Error setting pin mode or writing value: {e}")
                self.pi = None

    def set_value(self, value: int) -> None:
        if value not in [0, 1]:
            raise OutputPinError("Value must be 0 or 1.")

        try:
            self.pi.write(self.pin_number, value)
        except pigpio.Error as e:
            print(f"Error writing to pin: {e}")

    def shutdown(self) -> None:
        if self.pi is None:
            raise OutputPinError("No connection to pigpio daemon.")

        try:
            self.pi.set_mode(self.pin_number, pigpio.INPUT)
        except pigpio.Error as e:
