logging.basicConfig(level=logging.INFO)

class RotaryEncoder:
    def __init__(self, clk_pin=17, dt_pin=18, callback=None):
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback

        # GPIO setup
        try:
            self.encoder = gpiozero.RPIGPIO()
            self.encoder.setup_input_pull_up(self.clk_pin, True)
            self.encoder.setup_input_pull_up(self.dt_pin, True)
        except Exception as e:
            logging.error(f"Error setting up GPIO: {e}")
            raise

        # Debounce
        self.debounce_time = 0.02  # 20 ms
        self.last_clk_dt = None

        # Quadrature state transition table
        self.states = [
            (0, 1), (1, 0),  # Clockwise
            (0, 0), (1, 1)   # Counter-clockwise
        ]

        # Initialize counter
        self.counter = 0

        # Set up signal handlers
        self.signal_handler = signal.signal(signal.SIGINT, self.handle_signal)
        self.signal_handler = signal.signal(signal.SIGTERM, self.handle_signal)

    def handle_signal(self, signum, frame):
        logging.info(f"Received signal {signum}. Cleaning up...")
        self.cleanup()
        raise SystemExit(0)

    def poll(self):
        try:
            # Read GPIO pins
            current_clk = self.encoder.value(self.clk_pin)
            current_dt = self.encoder.value(self.dt_pin)

            # Debounce
            if self.last_clk_dt is not None:
                debounce_duration = time.time() - self.last_clk_dt
                if debounce_duration < self.debounce_time:
                    return

            self.last_clk_dt = time.time()

            # Determine state change
            last_state = self.last_clk_dt and (current_clk != self.encoder.value(self.clk_pin) or current_dt != self.encoder.value(self.dt_pin))
            current_state = (current_clk, current_dt)

            # Update counter based on state transition
            new_state = None
            for state in self.states:
                if state[0] == current_clk and state[1] == current_dt:
                    new_state = state
                    break

            if new_state:
                if new_state[0] != last_state:
                    self.counter += 1 if new_state[0] == 0 else -1

            # Notify callback
            if self.callback:
                self.callback(self.counter)

        except Exception as e:
            logging.error(f"Error during encoder polling: {e}")

    def cleanup(self):
        try:
            self.encoder.cleanup()
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")

    def run(self):
        while True:
            self.poll()
            time.sleep(0.01)  # Polling interval

    def __main__():
        try:
            encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=lambda x: print(f"Counter changed to: {x}"))
            encoder.run()
        except Exception as e:
            logging.error(f"Error in main: {e}")
            print("Exiting gracefully")

