import time
import RPi.GPIO as GPIO
import gpiozero
from gpiozero import Debounce
from threading import Event, Thread

class RotaryEncoder:
    def __init__(self, callback=None):
        self.callback = callback
        if callable(callback):
            self.is_callback_valid = True
        else:
            self.is_callback_valid = False
            print("Warning: Provided callback is not callable.")

        self.direction = 0
        self.debounce = Debounce(GPIO17, debounce_time=0.005)
        self.clk_rising_event = Event()
        self.clk_falling_event = Event()
        self.dt_previous_state = False

        GPIO.setmode(GPIO.BCM)
        GPIO.setup(GPIO17, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(GPIO18, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        self.thread = Thread(target=self._poll_encoder)
        self.thread.start()

    def _poll_encoder(self):
        while True:
            try:
                current_state = self.debounce.value()
                if current_state == GPIO.HIGH:
                    self.clk_rising_event.set()
                else:
                    self.clk_falling_event.set()

                if self.clk_rising_event.is_set():
                    if current_state != self.dt_previous_state:
                        self.dt_previous_state = current_state
                        if self.direction == 0 and current_state == GPIO.LOW:
                            self.direction = 1
                        elif self.direction == 1 and current_state == GPIO.HIGH:
                            self.direction = -1
                else:
                    if current_state != self.dt_previous_state:
                        self.dt_previous_state = current_state
                        if self.direction == 1 and current_state == GPIO.LOW:
                            self.direction = -1
                        elif self.direction == -1 and current_state == GPIO.HIGH:
                            self.direction = 1

                        if self.is_callback_valid:
                            self.callback(self.direction)

            except Exception as e:
                print(f"Error in encoder thread: {e}")

    def cleanup(self):
        GPIO.cleanup()
        self.debounce.close()
        self.clk_rising_event.clear()
        self.clk_falling_event.clear()
        self.thread.join()

    def __del__(self):
        self.cleanup()

    @staticmethod
    def debounce_time():
        return 0.005  # 5 ms debounce time

# Example usage in the main block
if __name__ == "__main__":
    def encoder_callback(direction):
        print(f"Rotation detected: {direction}")

    try:
        encoder = RotaryEncoder(callback=encoder_callback)
        time.sleep(5)  # Simulate some time passing
        # Simulate a keyboard interrupt
        raise KeyboardInterrupt
    except KeyboardInterrupt:
        print("Exiting due to KeyboardInterrupt.")
    finally:
        encoder.cleanup()
```

This code defines a `RotaryEncoder` class that interfaces with a KY-040 rotary encoder connected to GPIO17 (CLK) and GPIO18 (DT) on a Raspberry Pi using the `gpiozero` library. The class uses internal pull-up resistors for both pins and debounces the CLK signal with a debounce time of 5 ms. It detects rotation direction based on the rising and falling edges of the CLK signal and the current state of the DT pin. 

The `callback` function, if provided, is executed whenever a rotation is detected, wrapped in a try/except block to prevent the event thread from crashing. The `cleanup` method ensures that all GPIO resources are released properly, and the `__del__` destructor guarantees cleanup on object destruction.

In the `__main__` block, an example usage is provided, demonstrating how to set up the encoder with a callback function, simulating a period of time, and handling a `KeyboardInterrupt` gracefully, ensuring resources are released on all exit paths.

