from paho.mqtt.client import Client, CONNECTED, DISCONNECTED, Exception as MQTTException

# Configure logging
logging.basicConfig(filename='notification_light.log', level=logging.INFO)

# GPIO configuration
LED1_GPIO_PINS = (GPIO.PWM, 17, 18, 27)
LED2_GPIO_PINS = (GPIO.PWM, 22, 23, 24)
LED3_GPIO_PINS = (GPIO.PWM, 5, 6, 13)

# Initialize GPIO pins for LEDs
def initialize_LEDs():
    for led_info in [LED1_GPIO_PINS, LED2_GPIO_PINS, LED3_GPIO_PINS]:
        pin, r, g, b = led_info
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(pin, GPIO.OUT)
            led = RGBLED(r, g, b)
            led.off()
            GPIO.PWM(pin, 1000).pulse_width = 0  # Start with 0 duty cycle
            threading.Thread(target=led_thread, args=(pin,)).start()
        except Exception as e:
            logging.error(f"Error initializing LED {led_info}: {e}")

# Background thread to update LED colors
def led_thread(pin):
    while True:
        try:
            with threading.Lock():
                data = receive_data_from_socket()
                if data:
                    update_LEDs(data)
        except Exception as e:
            logging.error(f"Error in LED update thread: {e}")

# Function to receive data from the socket
def receive_data_from_socket():
    client = None
    while True:
        try:
            client = Client("tcp://192.168.1.100:5000")
            client.on_connect = on_connect
            client.on_disconnect = on_disconnect
            client.loop_start()
            data = client.recv_json()
            if data:
                return data
        except (socket.error, MQTTException) as e:
            logging.error(f"Error in data reception: {e}")
            time.sleep(1)  # Exponential backoff
            if time.time() > 60:  # Cap at 60 seconds
                time.sleep(60)

    return None

# Callback for connection
def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {rc}")
    client.subscribe("sensor/data")

# Callback for disconnection
def on_disconnect(client, userdata, rc):
    print(f"Disconnected with result code {rc}")
    time.sleep(1)  # Wait before reconnecting
    reconnect()

# Function to update LED colors based on received data
def update_LEDs(data):
    if data and all(0 <= val <= 100 for val in data.values()):
        cpu_usage, memory_usage, disk_io = data.values()
        if cpu_usage > 66:
            GPIO.PWM(LED1_GPIO_PINS[0].pin, 1000).duty_cycle = 255 * (cpu_usage / 100)
        elif 33 <= cpu_usage <= 66:
            GPIO.PWM(LED1_GPIO_PINS[0].pin, 1000).duty_cycle = 255 * (cpu_usage - 33) / (66 - 33)
        else:
            GPIO.PWM(LED1_GPIO_PINS[0].pin, 1000).duty_cycle = 0
        if memory_usage > 66:
            GPIO.PWM(LED2_GPIO_PINS[0].pin, 1000).duty_cycle = 255 * (memory_usage / 100)
        elif 33 <= memory_usage <= 66:
            GPIO.PWM(LED2_GPIO_PINS[0].pin, 1000).duty_cycle = 255 * (memory_usage - 33) / (66 - 33)
        else:
            GPIO.PWM(LED2_GPIO_PINS[0].pin, 1000).duty_cycle = 0
        if disk_io > 66:
            GPIO.PWM(LED3_GPIO_PINS[0].pin, 1000).duty_cycle = 255 * (disk_io / 100)
        elif 33 <= disk_io <= 66:
            GPIO.PWM(LED3_GPIO_PINS[0].pin, 1000).duty_cycle = 255 * (disk_io - 33) / (66 - 33)
        else:
            GPIO.PWM(LED3_GPIO_PINS[0].pin, 1000).duty_cycle = 0

# Main function
def main():
    initialize_LEDs()
    while True:
        time.sleep(1)  # Polling interval

if __name__ == "__main__":
    main()

import gpiozero
import random
import time

# Constants
GPIO_PIN = 17  # GPIO 17 (BCM)
PULL_UP = True  # Enable internal pull-up resistor
SAMPLES = 6
MAINTENANCE_THRESHOLD = 7.5

# Initialize the GPIO pin with pull-up
try:
    sensor = gpiozero.DigitalInput(PIN=GPIO_PIN, pull_up=PULL_UP)
    print(f"Sensor connected to GPIO {GPIO_PIN}")
except Exception as e:
    print(f"Error connecting to GPIO {GPIO_PIN}: {e}")
    exit(1)

# Function to simulate amplitude based on sensor state
def simulate_amplitude(sensor):
    amplitudes = []
    for _ in range(SAMPLES):
        try:
            reading = sensor.value  # Read sensor state
            if reading:
                # No vibration detected, simulate lower amplitude
                amplitude = random.uniform(3.0, 5.0)
            else:
                # Vibration detected, simulate higher amplitude
                amplitude = random.uniform(6.0, 9.0)
            amplitudes.append(amplitude)
        except Exception as e:
            print(f"Error reading sensor: {e}")
            continue
    return sum(amplitudes) / SAMPLES  # Calculate the running average

# Main logic
if __name__ == "__main__":
    try:
        while True:
            avg_amplitude = simulate_amplitude(sensor)
            if avg_amplitude > MAINTENANCE_THRESHOLD:
                print("Maintenance recommended: wear trend is high")
            else:
                print("Component healthy: no action needed")
            time.sleep(0.3)  # Wait for 0.3 seconds before next reading
    finally:
        # Ensure resources are released even if an exception occurred
        try:
            sensor.close()
        except Exception:
            pass
        print("Script execution completed.")

import logging
import serial
import smbus
import paho.mqtt.client as mqtt
import time
import json
import threading
import gpiozero
import signal

# Initialize logging
logging.basicConfig(level=logging.INFO, format='[%(asctime)s] [%(levelname)s] [%(message)s]')
logger = logging.getLogger(__name__)

# GPIO configuration (using gpiozero for simplicity)
led = gpiozero.LED(17)  # Example GPIO pin for status indication

# GPS module setup
try:
    import serial
    gps_serial = serial.Serial('/dev/ttyAMA0', 9600, timeout=2)
    gps_serial.isOpen()
    gps_present = True
    read_gps_position = read_gps_position_serial(gps_serial)
except (serial.SerialException, ValueError):
    try:
        import smbus
        bus = smbus.SMBus(1)  # I2C bus on Raspberry Pi
        gps_i2c = smbus.SlaveDevice(0x42)  # Address of Adafruit Ultimate GPS
        gps_i2c.read_byte()  # Check if the device is present
        gps_present = True
        read_gps_position = read_gps_position_i2c(gps_i2c)
    except (smbus.SMBusError, AttributeError):
        gps_present = False
        read_gps_position = lambda: {'lat': 0, 'lon': 0}

# MQTT client setup
client = mqtt.Client()
client.on_connect = on_connect
client.on_disconnect = on_disconnect
client.on_publish = on_publish
client.connect('localhost', 9099, 60)

# Signal handlers
def signal_handler(signal, frame):
    logger.info('Shutting down...')
    client.disconnect()
    gps_present = False  # Close GPS connection
    led.off()
    gpiozeroGPIO.cleanup()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main loop
def main():
    while True:
        try:
            client.loop_forever()
        except KeyboardInterrupt:
            pass

def read_gps_position_serial(gps_serial):
    if gps_present:
        while True:
            try:
                gps_data = gps_serial.readline().decode('utf-8')
                if gps_data.startswith('$GPGGA'):
                    position = gps_data.split(',')[-5:]
                    return {'lat': float(position[0]), 'lon': float(position[1])}
            except (serial.SerialException, ValueError):
                logger.error('Error reading from GPS module')
                time.sleep(2)
        logger.error('GPS module not found or disconnected')
    return {}

def read_gps_position_i2c(gps_i2c):
    if gps_present:
        while True:
            try:
                data = gps_i2c.read_byte_data(0x10, 0x3F)  # Command to read GPS data
                if data[0] == 0x2D:  # Check if valid GPS data
                    position = [data[1], data[2]]
                    return {'lat': position[0], 'lon': position[1]}
            except (smbus.SMBusError, IndexError):
                logger.error('Error reading from GPS module')
                time.sleep(2)
        logger.error('GPS module not found or disconnected')
    return {}

def handle_command(client, command):
    if command == 'start':
        led.on()
        gps_present = True  # Assume GPS is ready
    elif command == 'stop':
        led.off()
        gps_present = False  # Assume GPS is stopped
    elif command == 'report':
        position = read_gps_position()
        if gps_present:
            response = json.dumps(position)
            client.publish('iot/wildlife_tracker', response, qos=0)
        else:
            response = json.dumps({'error': 'GPS not available'})
            client.publish('iot/wildlife_tracker', response, qos=0)
    else:
        logger.error(f'Invalid command: {command}')

def on_connect(client, userdata, flags, rc):
    logger.info(f'Connected with result code {rc}')
    client.subscribe('iot/wildlife_tracker')

def on_disconnect(client, userdata, rc):
    logger.info(f'Disconnected with result code {rc}')

def on_publish(client, userdata, msg):
    logger.info(f'Published message {msg.topic} with QoS {msg.qos}')

if __name__ == '__main__':
    main()

