import logging
import time
import signal
import Adafruit_PCA9685
import Adafruit_MotorHAT
import Adafruit_DCMotorHATExtra

# Initialize logging
logging.basicConfig(level=logging.INFO)

# Define the DCMotorHATExtra class
class DCMotorHATExtra(Adafruit_MotorHAT):
    def __init__(self, bus=1, address=0x60):
        super().__init__(bus, address)
        self._default_pwm_freq = 60  # Hz
        self._i2c_bus = bus
        self._i2c_address = address

    def set_pwm_freq(self, freq):
        if 0 <= freq <= 4095:
            self._pwm_freq = freq
            logging.info(f"Setting PWM frequency to {freq} Hz")
        else:
            logging.warning(f"Invalid PWM frequency {freq} Hz, defaulting to {self._default_pwm_freq} Hz")

    @property
    def pwm_freq(self):
        return self._pwm_freq

    @staticmethod
    def release_motor_hats():
        try:
            Adafruit_MotorHAT.RELEASE()
        except Exception as e:
            logging.error(f"Error releasing motors: {e}")

    @staticmethod
    def register_atexit_handler():
        signal.signal(signal.SIGINT, DCMotorHATExtra.release_motor_hats)
        signal.signal(signal.SIGTERM, DCMotorHATExtra.release_motor_hats)

    @staticmethod
    def register_signal_handlers():
        DCMotorHATExtra.register_atexit_handler()

# Define the DCMotor class
class DCMotor(Adafruit_DCMotor):
    def __init__(self, motor_hat, motor_number, pwm_freq=None, invert=False):
        self._motor_hat = motor_hat
        self._motor_number = motor_number
        self._pwm_freq = pwm_freq if pwm_freq is not None else motor_hat.pwm_freq
        self._invert = invert
        self._last_duty_cycle = None

        self._motor_hat.register_atexit_handler()

        try:
            self._motor = Adafruit_DCMotor(self._motor_hat, self._motor_number, invert=invert)
        except Exception as e:
            logging.error(f"Error initializing motor {self._motor_number}: {e}")

    def set_dc(self, duty_cycle: int) -> None:
        if not -255 <= duty_cycle <= 255:
            duty_cycle = max(-255, min(255, duty_cycle))

        if duty_cycle == 0:
            self._motor.stop()
        else:
            direction = Adafruit_MotorHAT.FORWARD if (duty_cycle > 0 ^ self._invert) else Adafruit_MotorHAT.BACKWARD
            self._motor.setSpeed(abs(duty_cycle))
            self._last_duty_cycle = duty_cycle

    def stop(self) -> None:
        self._motor.stop()

    def close(self) -> None:
        self._motor.close()

    def get_status(self) -> tuple:
