import minimalmodbus
import signal

class ServoMotorController:
    def __init__(self, port='/dev/serial0', baudrate=115200, slave_address=1):
        self.port = port
        self.baudrate = baudrate
        self.slave_address = slave_address
        self.modbus = minimalmodbus.ModbusTCP()
        self.modbus.connect('127.0.0.1', 502)
        self.ser = None
        self.is_running = False
        self.signal_handler = signal.signal(signal.SIGINT, self.handle_signal)
        self.signal_handler = signal.signal(signal.SIGTERM, self.handle_signal)

    def _open_serial(self):
        try:
            self.ser = serial.Serial(self.port, self.baudrate, timeout=1, dsqrt=serial.DTRDSR_RTS)
            self.ser.flushInput()  # Clear any pending input
            self.ser.flushOutput()  # Clear any pending output
            print(f"Connected to {self.port} at {self.baudrate} baud.")
        except serial.SerialException:
            print(f"Error opening serial port {self.port}.")
            return False
        return True

    def _close_serial(self):
        if self.ser:
            self.ser.close()
            self.ser = None

    def start(self):
        if not self._open_serial():
            return False
        try:
            self.modbus.write_input_registers(self.slave_address, [0x3100], [0x000F])
            print("Servo started.")
            self.is_running = True
        except minimalmodbus.ModbusException as e:
            print(f"Error starting servo: {e}")
            self.is_running = False
        finally:
            self._close_serial()
        return self.is_running

    def stop(self):
        if not self.is_running:
            return
        if self._open_serial():
            try:
                self.modbus.write_input_registers(self.slave_address, [0x3100], [0x0006])
                print("Servo stopped.")
                self.is_running = False
            except minimalmodbus.ModbusException as e:
                print(f"Error stopping servo: {e}")
            finally:
                self._close_serial()
        return self.is_running

    def set_operation_mode(self, mode):
        if not isinstance(mode, int) or mode < 0 or mode > 1:
            raise ValueError("Mode must be an integer between 0 and 1.")
        if not self._open_serial():
            return
        try:
            self.modbus.write_input_register(self.slave_address, 0x3500, mode)
            print(f"Operation mode set to {mode}.")
        except minimalmodbus.ModbusException as e:
            print(f"Error setting operation mode: {e}")
        finally:
            self._close_serial()

    def write_position_command(self, value):
        if not isinstance(value, int) or value < 0 or value > 65535:
            raise ValueError("Position value must be an integer between 0 and 65535.")
        if not self._open_serial():
            return
        try:
            self.modbus.write_input_register(self.slave_address, 0x4000, value)
            print(f"Position command set to {value}.")
        except minimalmodbus.ModbusException as e:
            print(f"Error writing position command: {e}")
        finally:
            self._close_serial()

    def write_velocity_command(self, value):
        if not isinstance(value, int) or value < 0 or value > 255:
            raise ValueError("Velocity value must be an integer between 0 and 255.")
        if not self._open_serial():
            return
        try:
            self.modbus.write_input_register(self.slave_address, 0x6F00, value)
            print(f"Velocity command set to {value}.")
        except minimalmodbus.ModbusException as e:
            print(f"Error writing velocity command: {e}")
        finally:
            self._close_serial()

    def read_position_feedback(self):
        if not self._open_serial():
            return None
        try:
            position1, position2 = self.modbus.read_input_registers(self.slave_address, [0x3700], 2)
            return (position1, position2)
        except minimalmodbus.ModbusException as e:
            print(f"Error reading position feedback: {e}")
        finally:
            self._close_serial()

    def read_velocity_feedback(self):
        if not self._open_serial():
            return None
        try:
            velocity1, velocity2 = self.modbus.read_input_registers(self.slave_address, [0x3B00], 2)
            return (velocity1, velocity2)
        except minimalmodbus.ModbusException as e:
            print(f"Error reading velocity feedback: {e}")
        finally:
            self._close_serial()

    def read_status(self):
        if not self._open_serial():
            return None
        try:
            status = self.modbus.read_input_register(self.slave_address, 0x3000)
            return status
        except minimalmodbus.ModbusException as e:
            print(f"Error reading status: {e}")
        finally:
            self._close_serial()

    def handle_signal(self, signum, frame):
        print(f"Caught signal {signum}. Shutting down...")
        self.stop()
        sys.exit(0)

if __name__ == '__main__':
    try:
        servo_controller = ServoMotorController()
        if servo_controller.start():
            print("Demo started successfully.")
            time.sleep(5)  # Keep the demo running for 5 seconds
            servo_controller.write_position_command(32768)  # Move servo to mid position
            print("Position command sent.")
            position_feedback = servo_controller.read_position_feedback()
            if position_feedback:
                print(f"Current position feedback: {position_feedback}")
            servo_controller.stop()
            print("Demo stopped.")
        else:
            print("Failed to start the servo.")
    except Exception as e:
        print(f"Error occurred: {e}")
        # Ensure cleanup on exceptions
        if hasattr(servo_controller, '_close_serial'):
            servo_controller._close_serial()
    finally:
        # Ensure cleanup on exit
        if hasattr(servo_controller, '_close_serial'):
            servo_controller._close_serial()

