        self.bus = smbus2.SMBus(bus_number)
        try:
            self.bus.write_byte_data(address, 0x00, 0x00)  # Quick probe
        except (OSError, IOError) as e:
            raise RuntimeError("I2C device not found or not responding.") from e

    @contextmanager
    def __enter__(self):
        try:
            self.bus.begin()
            yield self
        finally:
            self.bus.stop()

    @contextmanager
    def __exit__(self, exc_type, exc_val, exc_tb):
        if exc_type:
            print(f"Error occurred: {exc_type}, {exc_val}, {exc_tb}")
            return False
        self.bus.stop()
        return True

    def write_byte(self, register, value):
        try:
            self.bus.write_byte_data(address, register, value)
        except (OSError, IOError) as e:
            raise RuntimeError("Error writing to I2C device.") from e

    def read_byte(self, register):
        try:
            return self.bus.read_byte_data(address, register)
        except (OSError, IOError) as e:
            raise RuntimeError("Error reading from I2C device.") from e

    def close(self):
        self.bus.stop()

# Example usage:
if __name__ == "__main__":
    try:
        with I2CDevice(0x54) as i2c_device:
            print(f"Writing byte to register 0x01: {i2c_device.write_byte(0x01, 0x55)}")
            print(f"Reading byte from register 0x01: {i2c_device.read_byte(0x01)}")
    except RuntimeError as e:
        print(e)
    finally:
        # Ensure resources are cleaned up even if an error occurred
        try:
            if hasattr(__import__('I2CDevice'), 'close'):
                I2CDevice().close()
        except Exception as e:
            print(f"Error closing I2C resources: {e}")
