            self.bus.write_byte_data(self.address, 0x06, year_low)
        except (OSError, ValueError):
            raise Exception("Error writing year register")

    def read_datetime(self, century=21):
        try:
            date = datetime.datetime(1900 + century, 1, 1)
            seconds = self.read_seconds()
            minutes = self.read_minutes()
            hours = self.read_hours()
            date = date + timedelta(hours=hours, minutes=minutes, seconds=seconds)
            month = self.read_month()
            year_low = self.read_year()
            year = 1900 + century * 100 + year_low
            return date.strftime("%Y-%m-%d %H:%M:%S")
        except Exception as e:
            raise e

    def write_all(self, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
