    try:
        ser.close()
    except Exception as e:
        print(f"Error closing serial port: {e}")
    print("Exiting gracefully...")

# Signal registration
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.ser = None
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout

        try:
            self.ser = serial.Serial(port=self.port, baudrate=self.baud_rate, timeout=self.timeout)
            self.ser.flushInput()  # Clear any pending input
            self._setup_gpio()
        except Exception as e:
            print(f"Error initializing serial port: {e}")
            self.ser = None

    def _setup_gpio(self):
        GPIO.setup(UART_RXD, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(UART_TXD, GPIO.OUT, initial=GPIO.LOW)

    def _send_command(self, command, timeout=1.0, wait_for=None):
        if not self.ser:
            return None

        try:
            self.ser.write(command.encode())
            self.ser.flush_output()

            response = self.ser.readline().decode('utf-8')
            if wait_for:
                if wait_for in response:
                    return response
                elif response.endswith(wait_for):
                    return response
            else:
                return response
        except (serial.SerialException, ValueError) as e:
            print(f"Error sending command: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT', timeout=2.0, wait_for='OK')
        return response == b'OK'

    def restart(self):
        self._send_command('AT+RST', timeout=5.0)
        response = self._send_command('AT', timeout=5.0)
        if 'ready' in response:
            return True
        else:
            time.sleep(2)
            response = self._send_command('AT', timeout=5.0)
            return 'ready' in response

    def connect_wifi(self, ssid, password):
        self._send_command('AT+CWJAP=' + ssid + ',' + password, timeout=10.0)

    def disconnect_wifi(self):
        self._send_command('AT+CWQAP')

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        if 'IP=' in response:
            return response.split('IP=')[1].strip()
        else:
            return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if not self.ser:
            return None

        response = self._send_command(f'AT+CIPSTART="TCP",{host}:{port}')
        if response:
            response = self._send_command(f'AT+CIPSEND,{len(data)}')
            if response:
                self.ser.write(data.encode())
                self.ser.flush_output()
                response = self._receive_http_response(timeout=5.0)
                self.ser.close()
                return response
        else:
            return None

    def _receive_http_response(self, timeout=5.0):
        while True:
            packet = self.ser.readline().decode('utf-8')
            if packet.startswith('CLOSED'):
                return None
            elif packet.startswith('+IPD,'):
                len_, data = packet.split(',', 1)
                return data.decode()

    def receive_http_response(self, timeout=5.0):
        response = self._receive_http_response(timeout=timeout)
        return response

if __name__ == '__main__':
    try:
        controller = ESP8266Controller()
        if controller.test_connection():
            print("Connection to ESP8266 successful.")
            # Example usage
            controller.connect_wifi('your_ssid', 'your_password')
            print(f"Connected to WiFi with IP: {controller.get_ip()}")
            controller.send_http_request('GET', 'http://example.com', 'example.com')
            response = controller.receive_http_response()
            print(f"HTTP Response: {response}")
        else:
            print("Failed to connect to ESP8266.")
    finally:
        # Ensure cleanup regardless of success or failure
        if controller.ser:
            controller.ser.close()

