    if not nmea_string.startswith('$GPRMC'):
        return None, None

    parts = nmea_string.split(',')
    if len(parts) != 8:
        return None, None

    latitude_raw = parts[4]
    longitude_raw = parts[5]

    # Convert ddmm.mmmm to decimal degrees
    def ddmm_to_decimal(degrees, minutes):
        return degrees + (minutes / 60.0)

    latitude_decimal = ddmm_to_decimal(int(latitude_raw[:2]), decimal.Decimal(latitude_raw[2:]))
    longitude_decimal = ddmm_to_decimal(int(longitude_raw[:2]), decimal.Decimal(longitude_raw[2:]))

    return latitude_decimal, longitude_decimal

# Main function
def main():
    try:
        # Initialize serial port
        ser = None
        try:
            ser = serial.Serial(port='/dev/serial0', baudrate=BAUD_RATE, timeout=TIMEOUT_SECONDS, 
                                dtype=serial.EIGHTBITS, stopbits=serial.STOPBITS_ONE)
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            return

        # Thread to handle serial reading
        reader_thread = threading.Thread(target=read_serial_data, args=(ser,))
        reader_thread.start()

        # Main loop until KeyboardInterrupt
        while True:
            try:
                time.sleep(1)
            except KeyboardInterrupt:
                break

        # Wait for the reader thread to finish
        reader_thread.join()

        # Close serial port
        if ser:
            ser.close()

    except Exception as e:
        print(f"Unexpected error: {e}")
        # Ensure resources are released
        if ser:
            ser.close()

# Function to read and process GPS data from the serial port
def read_serial_data(ser):
    while True:
        try:
            data = ser.readline()
            if not data:
                # No data available within timeout
                continue

            # Check if it's a valid GPRMC sentence
            latitude, longitude = parse_nmea_gprmc(data)
            if latitude is not None and longitude is not None and latitude.startswith('N') and longitude.startswith('E'):
                print(f"Latitude: {latitude}, Longitude: {longitude}")

            # Sleep for 1 second delay
            time.sleep(1)
        except serial.SerialException as e:
            print(f"Serial read error: {e}")
        except Exception as e:
            print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()
```

This script reads GPS data from the `/dev/serial0` port at 9600 baud, parses `$GPRMC` NMEA sentences to extract latitude and longitude, converts the coordinates from degrees, minutes, and seconds to decimal degrees, and prints them to the console. It includes error handling for serial port issues and gracefully handles resource release on all exit paths, including when interrupted with Ctrl+C. The script uses `threading` to ensure that the serial reading does not block the main execution loop.

