        signal.signal(signal.SIGINT, self.handle_int)
        signal.signal(signal.SIGTERM, self.handle_term)

    @contextmanager
    def open_serial(self):
        try:
            self.ser = serial.Serial(self.port, self.baud, timeout=1)
            self.ser.flushInput()  # Clear any pending input
            yield self.ser
        except serial.SerialException as e:
            raise Exception(f"Error opening serial port: {e}")
        finally:
            self.ser.close()

    def attach(self):
        with self.open_serial() as ser:
            ser.write('AT+CGNSPWR=1\r\n')
            time.sleep(1)
            if ser.inWaiting() == 0:
                raise Exception("Failed to send AT command or receive response.")
            response = ser.readline().strip()
            if 'OK' not in response:
                raise Exception(f"Expected 'OK', got: {response}")
            return True

    def detach(self):
        with self.open_serial() as ser:
            ser.write('AT+CGNSPWR=0\r\n')
            time.sleep(1)
            if ser.inWaiting() == 0:
                raise Exception("Failed to send AT command or receive response.")
            response = ser.readline().strip()
            if 'OK' not in response:
                raise Exception(f"Expected 'OK', got: {response}")
            return True

    def get_data(self):
        with self.open_serial() as ser:
            data = ser.readline().strip()
            if data.startswith('$GPRMC') and data[2] == 'A':
                return data.split(',')
            return None

    def close(self):
        if self.ser:
            self.ser.close()

    @staticmethod
    def handle_int(signal_num, frame):
        GPSController.close_all()  # Close all serial ports

    @staticmethod
    def handle_term(signal_num, frame):
        GPSController.close_all()  # Close all serial ports

    @staticmethod
    def close_all():
        for controller in [instance for instance in locals().values() if isinstance(instance, GPSController)]:
            controller.close()

