import logging
import serial
import time
from datetime import datetime
from typing import Dict

# Initialize logging
logging.basicConfig(level=logging.INFO)

class SimpleGPS:
    def __init__(self, port: str = '/dev/serial0', baud_rate: int = 9600):
        self.port = port
        self.baud_rate = baud_rate
        self.connected = False
        self.ser = None

    def connect(self) -> bool:
        try:
            self.ser = serial.Serial(self.port, self.baud_rate, timeout=1)
            self.connected = True
            logging.info(f"Connected to GPS device on {self.port} at {self.baud_rate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Error connecting to GPS: {e}")
            return False
        except OSError as e:
            logging.error(f"Error opening GPS device: {e}")
            return False

    def read_data(self) -> str:
        if not self.connected:
            return None

        try:
            data = self.ser.readline().decode('utf-8', errors='ignore').strip()
            return data
        except (serial.SerialException, ValueError) as e:
            logging.error(f"Error reading from GPS: {e}")
            return None

    def parse_gga(self, line: str) -> Dict or None:
        try:
            # Split the line into fields
            fields = line.split(',')
            if len(fields) != 8:
                logging.warning("Malformed GGA/NMEA sentence, skipping.")
                return None

            utc_time = datetime.fromisoformat(fields[0])
            lat_str, lon_str = fields[2], fields[3]

            # Convert latitude and longitude to decimal degrees
            try:
                lat_deg = float(lat_str.split()[0])
                lon_deg = float(lon_str.split()[0])
            except (ValueError, IndexError):
                logging.warning("Latitude or longitude coordinates are malformed, skipping.")
                return None

            latitude = lat_deg
            longitude = lon_deg

            fix_quality = int(fields[4])
            num_satellites = int(fields[6])

            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except Exception as e:
            logging.error(f"Error parsing GGA/NMEA sentence: {e}")
            return None

    def close(self):
        if self.ser:
            try:
                self.ser.close()
                self.ser = None
                logging.info("GPS connection closed.")
            except Exception as e:
                logging.error(f"Error closing GPS connection: {e}")

    def run(self):
        while True:
            line = self.read_data()
            if line is None:
                break

            parsed_data = self.parse_gga(line)
            if parsed_data is not None:
                logging.info(f"Received GGA data: {parsed_data}")

            time.sleep(1)  # Poll every second

if __name__ == "__main__":
    gps = SimpleGPS()
    gps.connect()
    try:
        gps.run()
    finally:
        gps.close()

