    def __init__(self):
        self.data = []

    def get_all(self):
        return self.data

    def get_by_id(self, item_id):
        return [item for item in self.data if item['id'] == item_id]

    def create(self, name, done):
        if not name:
            return {"error": "Name cannot be empty"}
        item = {"id": len(self.data) + 1, "name": name, "done": done}
        self.data.append(item)
        return item

